# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">DIŞ TİCARET KAVRAMLARI: İHRACAT, İTHALAT, HACİM VE DENGE (12.2.10)</text>\n  <rect x="20" y="45" width="210" height="115" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">İhracat (Dış Satım)</text>\n  <text x="125" y="90" text-anchor="middle" font-size="10.5" fill="#14532d">Ülkede üretilen mal ve</text>\n  <text x="125" y="106" text-anchor="middle" font-size="10.5" fill="#14532d">hizmetlerin dış pazarlara</text>\n  <text x="125" y="122" text-anchor="middle" font-size="10.5" fill="#14532d">satılmasıdır (Döviz girişi</text>\n  <text x="125" y="138" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">sağlar).</text>\n  <rect x="245" y="45" width="210" height="115" rx="10" fill="#fee2e2" stroke="#dc2626" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">İthalat (Dış Alım)</text>\n  <text x="350" y="90" text-anchor="middle" font-size="10.5" fill="#7f1d1d">Başka ülkelerden mal,</text>\n  <text x="350" y="106" text-anchor="middle" font-size="10.5" fill="#7f1d1d">enerji, ham madde veya</text>\n  <text x="350" y="122" text-anchor="middle" font-size="10.5" fill="#7f1d1d">ara malı satın alınmasıdır</text>\n  <text x="350" y="138" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#b91c1c">(Döviz çıkışı olur).</text>\n  <rect x="470" y="45" width="210" height="115" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">Dış Ticaret Hacmi</text>\n  <text x="575" y="94" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1d4ed8">Hacim = İhracat + İthalat</text>\n  <text x="575" y="116" text-anchor="middle" font-size="10.5" fill="#1e3a8a">Bir ülkenin küresel ticaret</text>\n  <text x="575" y="132" text-anchor="middle" font-size="10.5" fill="#1e3a8a">ağındaki toplam büyüklüğünü</text>\n  <text x="575" y="146" text-anchor="middle" font-size="10" fill="#1e3a8a">gösterir.</text>\n  <rect x="20" y="172" width="320" height="72" rx="8" fill="#fef3c7" stroke="#d97706" stroke-width="1.8"/>\n  <text x="180" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#92400e">Dış Ticaret Açığı (İthalat &gt; İhracat)</text>\n  <text x="180" y="213" text-anchor="middle" font-size="10.5" fill="#78350f">Dış alım giderinin dış satım gelirinden fazla olmasıdır;</text>\n  <text x="180" y="229" text-anchor="middle" font-size="10" fill="#78350f">Türkiye\'de enerji ithalatı açığın temel nedenidir.</text>\n  <rect x="360" y="172" width="320" height="72" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="520" y="194" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">Dış Ticaret Fazlası (İhracat &gt; İthalat)</text>\n  <text x="520" y="213" text-anchor="middle" font-size="10.5" fill="#14532d">Dış satım gelirinin dış alım giderini aşmasıdır;</text>\n  <text x="520" y="229" text-anchor="middle" font-size="10" fill="#14532d">yüksek katma değerli teknoloji üretimiyle sağlanır.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">TÜRKİYE\'NİN İHRACAT VE İTHALATININ SEKTÖREL VE ÜRÜN DAĞILIMI</text>\n  <rect x="25" y="45" width="310" height="198" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">İhracat (Dış Satım) Yapısı</text>\n  <text x="40" y="92" font-size="11" font-weight="bold" fill="#1d4ed8">• Sektörel Pay: ~%94 Sanayi Ürünleri</text>\n  <text x="40" y="110" font-size="10.5" fill="#1e3a8a">(Tarım ~%4, Madencilik ~%2 paya sahiptir)</text>\n  <text x="40" y="135" font-size="11" font-weight="bold" fill="#1e3a8a">• Başlıca İhraç Ürünlerimiz:</text>\n  <text x="48" y="153" font-size="10.5" fill="#1e3a8a">1. Motorlu kara taşıtları, otomotiv ve yedek parça</text>\n  <text x="48" y="170" font-size="10.5" fill="#1e3a8a">2. Kazanlar, makineler, elektrikli cihazlar (beyaz eşya)</text>\n  <text x="48" y="187" font-size="10.5" fill="#1e3a8a">3. Demir-çelik ürünleri ve kıymetli taş/metaller</text>\n  <text x="48" y="204" font-size="10.5" fill="#1e3a8a">4. Tekstil, hazır giyim ve konfeksiyon ürünleri</text>\n  <text x="48" y="221" font-size="10.5" fill="#1e3a8a">5. Tarım-gıda: Fındık, incir, kayısı, kiraz, un, makarna</text>\n  <rect x="365" y="45" width="310" height="198" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">İthalat (Dış Alım) Yapısı</text>\n  <text x="380" y="92" font-size="11" font-weight="bold" fill="#b91c1c">• Mal Grubu: ~%75 Ara Malı ve Ham Madde</text>\n  <text x="380" y="110" font-size="10.5" fill="#7f1d1d">(Yatırım/sermaye malları ~%14, Tüketim ~%11)</text>\n  <text x="380" y="135" font-size="11" font-weight="bold" fill="#7f1d1d">• Başlıca İthal Ürünlerimiz:</text>\n  <text x="388" y="153" font-size="10.5" fill="#7f1d1d">1. Mineral yakıtlar ve yağlar (Ham petrol, doğal gaz)</text>\n  <text x="388" y="170" font-size="10.5" fill="#7f1d1d">2. Fabrika makineleri, kazanlar ve mekanik cihazlar</text>\n  <text x="388" y="187" font-size="10.5" fill="#7f1d1d">3. Elektrikli-elektronik cihazlar ve optik aletler</text>\n  <text x="388" y="204" font-size="10.5" fill="#7f1d1d">4. Demir-çelik hurdası, plastik ve organik kimyasallar</text>\n  <text x="388" y="221" font-size="10.5" fill="#7f1d1d">5. İlaç ve eczacılık ürünleri, tropikal tarım ürünleri</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14" font-weight="bold" fill="#0f172a">BAŞLICA TİCARET ORTAKLARIMIZ VE TAŞIMA TÜRLERİ PAYI</text>\n  <rect x="20" y="45" width="215" height="195" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="127" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#166534">En Çok İhracat Yapılan Ülkeler</text>\n  <text x="35" y="95" font-size="11" font-weight="bold" fill="#14532d">1. Almanya (1. sırada)</text>\n  <text x="35" y="117" font-size="11" fill="#14532d">2. ABD ve Birleşik Krallık</text>\n  <text x="35" y="139" font-size="11" fill="#14532d">3. İtalya ve İspanya</text>\n  <text x="35" y="161" font-size="11" fill="#14532d">4. Irak ve Fransa</text>\n  <rect x="32" y="180" width="190" height="46" rx="6" fill="#ffffff" stroke="#22c55e"/>\n  <text x="127" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">Avrupa Birliği (AB) ülkeleri toplam</text>\n  <text x="127" y="214" text-anchor="middle" font-size="10" font-weight="bold" fill="#15803d">ihracatımızın ~%41\'ini oluşturur.</text>\n  <rect x="247" y="45" width="215" height="195" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="354" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#92400e">En Çok İthalat Yapılan Ülkeler</text>\n  <text x="262" y="95" font-size="11" font-weight="bold" fill="#78350f">1. Rusya ve Çin (İlk 2 sıra)</text>\n  <text x="262" y="117" font-size="11" fill="#78350f">2. Almanya ve ABD</text>\n  <text x="262" y="139" font-size="11" fill="#78350f">3. İsviçre ve İtalya</text>\n  <text x="262" y="161" font-size="11" fill="#78350f">4. Hindistan ve Fransa</text>\n  <rect x="260" y="180" width="190" height="46" rx="6" fill="#ffffff" stroke="#f59e0b"/>\n  <text x="354" y="198" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">Rusya\'dan enerji, Çin\'den elektronik</text>\n  <text x="354" y="214" text-anchor="middle" font-size="10" font-weight="bold" fill="#b45309">ve makine/ara malı ithal edilir.</text>\n  <rect x="475" y="45" width="205" height="195" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="577" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">Ulaşım Türleri ve Serbest Bölge</text>\n  <text x="488" y="95" font-size="11" font-weight="bold" fill="#1e3a8a">• Deniz Yolu: ~%55 - %60</text>\n  <text x="496" y="111" font-size="10" fill="#1e3a8a">(Tek seferde yüksek tonaj, ucuz)</text>\n  <text x="488" y="133" font-size="11" font-weight="bold" fill="#1e3a8a">• Kara Yolu: ~%28 - %32</text>\n  <text x="488" y="155" font-size="11" font-weight="bold" fill="#1e3a8a">• Hava Yolu: ~%8 - %12</text>\n  <text x="488" y="177" font-size="11" font-weight="bold" fill="#1e3a8a">• Demir Yolu: ~%1 - %2</text>\n  <text x="488" y="202" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Serbest Bölgeler:</text>\n  <text x="496" y="218" font-size="10" fill="#1e3a8a">Mersin, İzmir, İstanbul, Bursa</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
